OUT=ROOT/'_AgentScratch/tmp/GeometryRepairs'
GALLERY=ROOT/'Exhibits/Gallery/Editor'
broad=json.loads((OUT/'Broad/results.json').read_text());analytic=json.loads((OUT/'analytic.json').read_text());complex_results=json.loads((OUT/'Complex/results.json').read_text());complex_audit=json.loads((OUT/'Complex/audit.json').read_text());legacy=json.loads((OUT/'legacy.json').read_text())
plan=json.loads((OUT/'UI/capture-plan.json').read_text());browser=json.loads((OUT/'UI/captures.json').read_text());native_ui=json.loads((GALLERY/'GeometryRepairsNativeUI.json').read_text())
assert broad['accepted']==56 and len(broad['newAcceptances'])==7 and broad['newRefusals']==['torus-box-union']
assert broad['nativeBinarySha256']==complex_results['nativeBinarySha256']==hashlib.sha256((ROOT/'_AgentScratch/build/SolidArcNative/GeometryHost').read_bytes()).hexdigest()
assert len(native_ui)==len(browser['ui'])==5 and sum(c['Apply'] for c in browser['ui'])==4
assert not browser['pageErrors'] and all(c['rgbaUploads']==0 for c in browser['captures'])
assert complex_results['engineAccepted']==27 and complex_results['testFailures']==complex_results['timeouts']==0
assert all(row['status']=='sampled-check-passed' for key in ['stages','sources','finals'] for row in complex_audit[key])
assert all(r['exitCode']==0 for r in legacy)
audit_by_id={a['id']:a for a in analytic['audits']};selected=[r for r in broad['cases'] if r['fixture'] in ['cone-box','torus-box']]
images={}
def add(key,path):
    packed=compressed_png(path.read_bytes())
    if path.parent==GALLERY and len(packed)<path.stat().st_size:path.write_bytes(packed)
    images[key]='data:image/png;base64,'+base64.b64encode(packed).decode()
for row in selected:
    id='repair-'+row['id'];fixture='repair-'+row['fixture']
    if 'native:'+fixture+':source' not in images:add('native:'+fixture+':source',GALLERY/f'GeometryRepairs-{fixture}-source.png')
    add('native:'+id+':boolean',GALLERY/f'GeometryRepairs-{id}-boolean.png')
    if any(ui['id']==id for ui in native_ui):
        for renderer in ['native','gpu']:
            for stage in ['ui-before-apply','ui-result']:
                path=GALLERY/f'GeometryRepairs-{id}-{stage}.png' if renderer=='native' else OUT/f'UI/images/{id}-html-{stage}.png'
                add(renderer+':'+id+':'+stage,path)
for row in browser['captures']:add('gpu:'+row['id']+':'+row['stage'],ROOT/row['path'])
assert len(images)==39
baseline=dict(description='2026-10-17 first generic Boolean split/assembly repair batch; periodic audit limitations remain open.',nativeBinarySha256=broad['nativeBinarySha256'],broadSummary={k:v for k,v in broad.items() if k!='cases'},cases=[{k:v for k,v in row.items() if k!='stages'} for row in broad['cases']],analyticAudit=analytic,complexSummary={k:v for k,v in complex_results.items() if k not in ('fixtures','scope')},complexAuditCounts=complex_audit['counts'],nativeRegression=dict(checks=92,failed=0,beforeFixFailed=59,scope='18 ordered cone operations at scales 1, 0.1 and 2 plus periodic safety'),legacy=legacy,nativeUI=native_ui,htmlUI=browser['ui'])
(ROOT/'Experimental/SolidArc/Native/Fixtures/BooleanRepairBaseline.json').write_text(json.dumps(baseline,indent=2)+'\n')
payload=dict(cases=selected,audits=audit_by_id,images=images,nativeUI=native_ui,htmlUI=browser['ui'],baseline=baseline)
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SolidArc · First Boolean kernel repairs</title><style>:root{color-scheme:dark}body{margin:0;background:#11151b;color:#e0e8f3;font:16px/1.55 system-ui}main{max-width:1240px;margin:36px auto;padding:0 22px}h1{font-size:34px}a{color:#aacfff}.note{padding:16px;background:#29251d;border-left:4px solid #d8b77c}.cards,.controls{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.cards div{padding:15px;border:1px solid #435169;background:#202936;border-radius:8px}.cards strong{display:block;font-size:27px}button,select{font:inherit;border:1px solid #57677b;background:#263346;color:inherit;padding:9px;border-radius:6px}button{cursor:pointer}button:disabled{opacity:.35;cursor:not-allowed}button[aria-pressed=true]{background:#c7dbf4;color:#0e1521}article{border:1px solid #536783;border-radius:10px;padding:18px;background:#1b2431}img{width:100%;display:block;border:1px solid #52657c}pre{overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;padding:14px;background:#111a27}figure{margin:16px 0}figcaption,#status{padding:10px;background:#263346}li{margin:9px 0}table{border-collapse:collapse;width:100%}td,th{padding:9px;border:1px solid #526078;text-align:left}.ok{color:#9adeb3}.pending{color:#f0cf96}</style></head><body><main>
<p>Native C++ kernel · repair batch 1 · 2026-10-17</p><h1>Cone code confirmed. Boolean splitting repaired.</h1>
<p>The cone primitive was already implemented: exact rational revolution, sewn/capped solid, console command and face-edit/blend support. The failure was in generic Boolean face splitting—not missing cone construction.</p>
<div class="cards"><div><strong>4 / 4</strong>original cone/box operations repaired</div><div><strong>92 / 92</strong>new C++ checks pass</div><div><strong>167 / 167</strong>related native checks pass</div><div><strong>27 / 27</strong>accepted complex finals retain audit passes</div></div>
<p class="note"><strong>Not all geometry gaps are fixed.</strong> The old torus/box union now refuses safely instead of dropping the torus. Three other torus operations now accept, but independent mesh audits remain <strong>inconclusive</strong> due excessive two-ray disagreement. Those are observations, not certified repairs. The complex construction blockers and scaled-concave order asymmetry remain open.</p>
<p><a href="/proofs">Historical broad audit</a> · <a href="/gpu/proofs/complex.html">Historical complex audit</a> · <a href="/gpu/">HTML GPU editor</a> · <a href="/cpp">C++ mirror</a></p>
<article><h2>Inspect the actual results</h2><div class="controls"><label>Case <select id="case"></select></label><button data-renderer="native">Native C++ / CPU reference</button><button data-renderer="gpu">Native geometry / WebGL2</button></div><div class="controls"><button data-view="source">Source solids</button><button data-view="boolean">Result / refusal</button><button data-view="ui-before-apply">Own mouse · before</button><button data-view="ui-result">Own mouse · result / guard</button></div><p id="outcome"></p><output id="status" role="status"></output><figure><img id="image" alt="Recorded C++ repair proof"><figcaption id="caption"></figcaption></figure><details open><summary>Exact commands, topology, independent audit</summary><pre id="details"></pre></details></article>
<h2>What changed in C++</h2><ol><li><strong>Boundary-knot identity:</strong> an intersection exit exactly on an existing face-domain sample now reuses the cut endpoint's graph identity. Previously the graph disconnected at quarter-circle cap samples.</li><li><strong>Closed-edge seam spans:</strong> spans no longer merge across a closed coedge’s end/start parameter jump. Previously trimming by min/max could substitute the complementary circular arc.</li><li><strong>Assembly safety:</strong> every traced transversal cut must survive on two distinct result faces. Final solid/finite-positive-volume validation happens in the kernel too, rather than only in the console. No guards or modelling inputs were weakened/nudged.</li></ol>
<h2>Independent evidence and limits</h2><ul><li>The new C++ regression exercises six ordered operations on the cone/box pair at scales 1, 0.1 and 2 (the latter translated), topology, top-cap material witnesses, volume identities and periodic safety. It exposed <strong>59 failed checks before the fix; 92/92 pass after</strong>. Curved native volumes remain approximate quadrature and use the declared 1% allowance.</li><li>All four original cone operations pass <strong>16,384 analytic-reference probes each</strong>, with zero non-boundary mismatches or two-ray disagreements. Ground truth uses the intended cone/box equations, not returned source meshes. Reference volumes independently integrate analytic disk/rectangle sections; numerical residuals remain in the diagnostics.</li><li>64-case Boolean-only rerun: 56 engine-accepted, 8 refused. All 49 previously spatial-passing accepted cases remain accepted. Seven new acceptances: four cone cases plus three <em>uncertified</em> periodic observations. The previous incorrectly accepted torus union now refuses atomically. The older broad bevel sweep is not rerun or newly certified.</li><li>24 complex pairings rerun: 127 intermediate bodies, 26 completed source bodies, 27 accepted final results retain their independent audit passes. Still 51 final refusals and 66 planned finals blocked by 11 construction failures; no timeouts or transaction assertion failures.</li><li>Six related native verification executables pass 167 checks. Two stale assertions expected marched SSI curves for boxes already handled by the exact arrangement route; both failures were reproduced with the pre-fix kernel, then corrected to expect zero fictitious curves. Exact volume/area/topology assertions remain intact.</li><li>Four actual mouse/Shift/Inspector/Apply cone operations and one disabled torus-union guard pass in <strong>both native ImGui and HTML</strong>, separately from command tests and nine WebGL2 draw-packet replays. Native color is CPU reference; WebGL2 uses software ANGLE, not a physical GPU. No CPU RGBA uploads. The guard has no Apply popup.</li><li>Existing services/drawing were not reset. The newly built kernel is used by new isolated sessions; already-running user document processes were deliberately not replaced. Existing sessions require a separately checkpointed upgrade to use the new binary.</li></ul>
<p>Progress and remaining work: <code>Experimental/SolidArc/Native/GEOMETRY_REPAIR_PROGRESS.md</code>, <code>GEOMETRY_GAPS.md</code>, and <code>Fixtures/BooleanRepairBaseline.json</code>.</p><button id="download">Download repair observations</button>
<script id="evidence" type="application/json">PAYLOAD</script><script>
const data=JSON.parse(document.querySelector('#evidence').textContent);let selected=data.cases[0].id,renderer='native',view='boolean';
const selector=document.querySelector('#case');for(const row of data.cases){const o=document.createElement('option');o.value=row.id;o.textContent=row.id;selector.append(o);}
function key(kind){const row=data.cases.find(c=>c.id===selected);if(kind==='source')return renderer+':repair-'+row.fixture+':source';if(kind==='boolean'&&!row.accepted&&renderer==='gpu')return renderer+':repair-'+row.fixture+':source';return renderer+':repair-'+row.id+':'+kind;}
function render(){const row=data.cases.find(c=>c.id===selected),audit=data.audits[selected];if(!data.images[key(view)])view='boolean';for(const b of document.querySelectorAll('[data-view]')){b.disabled=!data.images[key(b.dataset.view)];b.setAttribute('aria-pressed',String(b.dataset.view===view));}for(const b of document.querySelectorAll('[data-renderer]'))b.setAttribute('aria-pressed',String(b.dataset.renderer===renderer));
 const outcome=!row.accepted?'SAFE REFUSAL: torus union remains unsupported; sources unchanged.':audit.status==='sampled-check-passed'?'REPAIRED FIXTURE: accepted; intended-geometry checks pass.':'AUDIT INCONCLUSIVE: engine-accepted periodic output is NOT a certified repair.';document.querySelector('#outcome').textContent=outcome;document.querySelector('#outcome').className=audit?.status==='sampled-check-passed'?'ok':'pending';
 const provenance=view.startsWith('ui-')?(renderer==='native'?'Actual native ImGui mouse inputs / CPU reference':'Actual HTML mouse inputs / software WebGL2'):(renderer==='native'?'Actual native C++ ImGui capture / CPU reference':'Native draw-packet replay / real software WebGL2');const state=selected+' · '+view+' · '+provenance+' · '+outcome+(view.startsWith('ui-')&&!row.accepted?' Disabled before popup; no Apply available.':'');document.querySelector('#status').textContent=state;document.querySelector('#caption').textContent=state;const image=document.querySelector('#image');image.src=data.images[key(view)];image.alt=state;document.querySelector('#details').textContent=JSON.stringify({commands:['reset',...row.commands,row.command],operation:row,independentAudit:audit||'Safe refusal; no result to audit'},null,2);}
selector.onchange=e=>{selected=e.target.value;render();};for(const b of document.querySelectorAll('[data-renderer]'))b.onclick=()=>{renderer=b.dataset.renderer;render();};for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{view=b.dataset.view;render();};document.querySelector('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data.baseline,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='SolidArcBooleanRepairObservations.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};render();
</script></main></body></html>'''
html=html.replace('PAYLOAD',json.dumps(payload,separators=(',',':')))
target=GALLERY/'SolidArcBooleanRepairProof.html';target.write_text(html)
public=ROOT/'Experimental/SolidArc/dist/proofs/repairs.html';public.write_text(html)
